import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def objects(grid):
    h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]; objs=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]==grid[i][j]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                objs.append(cells)
    return objs

def transform(grid):
    h,w=len(grid),len(grid[0])
    objs=objects(grid)
    objs.sort(key=lambda c: -max(x for y,x in c))
    out=[[0]*w for _ in range(h)]
    for cells in objs:
        maxd=w-1-max(x for y,x in cells)
        for d in range(maxd,-1,-1):
            if all(0<=y<h and x+d<w and out[y][x+d]==0 for y,x in cells):
                for y,x in cells: out[y][x+d]=grid[y][x]
                break
    return out

o=transform(G['Demo pair 1 input']); print(o==G['Demo pair 1 output'])
print(json.dumps(transform(G['Test input'])))

